// Customize Theme: hand-written FABi page (user 2026-10-13: "chỉ có 5 theme", no antd version history).
// The FABi CMS Design System has 5 brands × Light / Dark, plus the compact density. No longer generated by
// scripts/convert-pages.mjs.
import { Markdown as DocMarkdown, Unstyled as DocUnstyled } from '@storybook/addon-docs/blocks'
import { BRANDS, DEFAULT_BRAND } from '@fabi/ui'
import { useDocsLocale } from '../../../.storybook/locale'
import Example from '../Example'
import BrandMode from './_demo/brand-mode'
import BrandModeSource from './_demo/brand-mode.tsx?raw'
import DarkArea from './_demo/dark-area'
import DarkAreaSource from './_demo/dark-area.tsx?raw'
import UseToken from './_demo/use-token'
import UseTokenSource from './_demo/use-token.tsx?raw'

const TEXT = {
  vi: {
    title: 'Tuỳ chỉnh theme',
    intro:
      'FABi CMS Design System có **5 theme** (5 brand), mỗi brand có **Light** và **Dark**. Bạn không cần tự tạo theme: chọn brand và chế độ ở `FabiProvider` là đủ. Màu của nút chính, link, focus, mục menu đang chọn… đều đi theo brand; màu trạng thái (thành công, cảnh báo, lỗi) và màu chữ, nền giữ nguyên ở mọi brand.',
    brands: '## 5 brand',
    cols: ['Brand', 'Mã `brand`', 'Màu chính'],
    default: 'mặc định',
    brandsNote: 'Màu chính là một bậc trong dải màu của brand, chọn sao cho chữ trắng trên nút chính đạt độ tương phản ≥ 4.5:1.',
    use: '## Dùng trong app\n\nBọc app **một lần** ở gốc. Đổi brand hay chế độ lúc đang chạy chỉ là đổi prop:',
    demo: 'Chọn brand, Light / Dark và Compact: các component bên dưới đổi theo ngay.',
    compact:
      '## Chế độ compact\n\nDành cho màn nhiều dữ liệu (bảng dày, form dài): control cao **28px** thay vì 32px, khoảng cách và chữ gọn hơn. Dùng được với cả Light và Dark:',
    nested:
      '## Một vùng khác chế độ\n\nCần một vùng tối trên trang sáng (ví dụ các nút trên header, trình xem ảnh): lồng thêm một `FabiProvider mode="dark"` quanh vùng đó. Vùng con giữ brand của trang, chỉ đổi chế độ.',
    nestedDemo: 'Header của template Dashboard dùng đúng cách này cho các nút AI, ngôn ngữ, thông báo.',
    tokens:
      '## Dùng token trong code của bạn\n\nKhi tự dựng khối giao diện, lấy màu, khoảng cách, bo góc từ `theme.useToken()`, **không dán mã hex**: khối sẽ tự đổi theo brand, Dark mode và Compact. Danh sách token xem ở các trang Colors, Font, Layout, Shadow, Responsive.',
    tokensDemo: 'Khối dùng `colorPrimaryBg`, `colorPrimaryBorder`, `colorPrimaryText`, `padding` và `borderRadiusLG`.',
    rules:
      '## Không tự chỉnh màu\n\n- Không đổi `colorPrimary` hay thêm màu ngoài palette qua prop `theme`: mọi màn hình FABi phải dùng một trong 5 brand.\n- Cần brand mới: thêm ở thiết kế trước, rồi thêm vào `BRANDS` trong `@fabi/ui` (theme.ts).\n- Prop `theme` của `FabiProvider` chỉ dùng cho trường hợp đặc biệt như compact; giá trị được gộp lên theme FABi, không thay thế nó.',
  },
  en: {
    title: 'Customize Theme',
    intro:
      'The FABi CMS Design System has **5 themes** (5 brands), each in **Light** and **Dark**. You never build a theme yourself: pick the brand and the mode on `FabiProvider`. The primary button, links, focus and the selected menu item follow the brand; status colours (success, warning, error), text and surfaces stay the same in every brand.',
    brands: '## 5 brands',
    cols: ['Brand', '`brand` key', 'Primary colour'],
    default: 'default',
    brandsNote: 'The primary colour is one step of the brand palette, chosen so white text on the primary button reaches at least 4.5:1.',
    use: '## Use it in the app\n\nWrap the app **once** at the root. Switching brand or mode at run time is just a prop change:',
    demo: 'Pick a brand, Light / Dark and Compact: the components below follow at once.',
    compact:
      '## Compact\n\nFor data-heavy screens (dense tables, long forms): controls are **28px** tall instead of 32px, with tighter spacing and text. Works with both Light and Dark:',
    nested:
      '## A different mode for one area\n\nNeed a dark area on a light page (e.g. the header buttons, an image viewer): wrap that area in another `FabiProvider mode="dark"`. The area keeps the page brand and only changes the mode.',
    nestedDemo: 'The Dashboard template header uses exactly this for the AI, language and notification buttons.',
    tokens:
      '## Use tokens in your own code\n\nWhen you build your own blocks, take colours, spacing and radii from `theme.useToken()`, **never paste hex values**: the block then follows the brand, Dark mode and Compact. The token lists are on the Colors, Font, Layout, Shadow and Responsive pages.',
    tokensDemo: 'The block uses `colorPrimaryBg`, `colorPrimaryBorder`, `colorPrimaryText`, `padding` and `borderRadiusLG`.',
    rules:
      "## Don't change the colours\n\n- Don't change `colorPrimary` or add colours outside the palette through the `theme` prop: every FABi screen uses one of the 5 brands.\n- Need a new brand: add it in the design first, then to `BRANDS` in `@fabi/ui` (theme.ts).\n- The `theme` prop of `FabiProvider` is only for special cases such as compact; it is merged over the FABi theme, not instead of it.",
  },
}

const ROOT_CODE = `import { FabiProvider } from '@fabi/ui'

<FabiProvider brand="cyan" mode="dark">
  <App />
</FabiProvider>`

const COMPACT_CODE = `import { FabiProvider, theme } from '@fabi/ui'

<FabiProvider brand="geekblue" mode="light" theme={{ algorithm: theme.compactAlgorithm }}>
  <App />
</FabiProvider>`

const code = (src: string) => `\n\n\`\`\`tsx\n${src}\n\`\`\``

export default function CustomizeThemePage() {
  const t = TEXT[useDocsLocale() === 'vi' ? 'vi' : 'en']
  return (
    <>
      <h1 className="fabi-sb-page-title">{t.title}</h1>
      <DocMarkdown>{`${t.intro}\n\n${t.brands}`}</DocMarkdown>
      <DocUnstyled>
        <div className="fabi-sb-block" style={{ overflowX: 'auto' }}>
          <table style={{ borderCollapse: 'collapse', width: '100%' }}>
            <thead>
              <tr>
                {t.cols.map((c) => (
                  <th key={c} scope="col" style={{ textAlign: 'start', padding: '8px 12px', borderBottom: '1px solid rgba(0,0,0,0.06)' }}>
                    <DocMarkdown>{c}</DocMarkdown>
                  </th>
                ))}
              </tr>
            </thead>
            <tbody>
              {Object.entries(BRANDS).map(([key, b]) => {
                const hex = b.palette[b.step - 1]
                return (
                  <tr key={key}>
                    <td style={{ padding: '8px 12px', borderBottom: '1px solid rgba(0,0,0,0.06)' }}>
                      {b.name}
                      {key === DEFAULT_BRAND && ` (${t.default})`}
                    </td>
                    <td style={{ padding: '8px 12px', borderBottom: '1px solid rgba(0,0,0,0.06)' }}><code>{key}</code></td>
                    <td style={{ padding: '8px 12px', borderBottom: '1px solid rgba(0,0,0,0.06)' }}>
                      <span style={{ display: 'inline-flex', alignItems: 'center', gap: 8 }}>
                        <span aria-hidden style={{ width: 24, height: 24, borderRadius: 4, background: hex, display: 'inline-block' }} />
                        <code>{hex}</code>
                      </span>
                    </td>
                  </tr>
                )
              })}
            </tbody>
          </table>
        </div>
      </DocUnstyled>
      <DocMarkdown>{`${t.brandsNote}\n\n${t.use}${code(ROOT_CODE)}`}</DocMarkdown>
      <Example code={BrandModeSource} description={t.demo}><BrandMode /></Example>
      <DocMarkdown>{`${t.compact}${code(COMPACT_CODE)}\n\n${t.nested}`}</DocMarkdown>
      <Example code={DarkAreaSource} description={t.nestedDemo}><DarkArea /></Example>
      <DocMarkdown>{t.tokens}</DocMarkdown>
      <Example code={UseTokenSource} description={t.tokensDemo}><UseToken /></Example>
      <DocMarkdown>{t.rules}</DocMarkdown>
    </>
  )
}
